INSERT INTO _migration_590_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_waves_b003_001', 'topic_wassce_intsci_waves', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The image formed by a plane mirror is always', 'multiple_choice', NULL, '["A. real, inverted and diminished","B. virtual, inverted and magnified","C. virtual, upright and the same size as the object","D. real, upright and the same size as the object"]', 'C', 'A plane mirror forms an image that is virtual (the rays only appear to come from behind the mirror), upright, the same size as the object and laterally inverted. It is never real or upside down. Therefore the correct answer is C: virtual, upright and the same size as the object.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL),
('q_wisc_waves_b003_002', 'topic_wassce_intsci_waves', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Sound waves cannot travel through a vacuum because sound', 'multiple_choice', NULL, '["A. travels too fast to pass through empty space","B. is an electromagnetic wave","C. is completely absorbed by any empty space","D. requires a material medium to transmit its vibrations"]', 'D', 'Sound is a mechanical wave: it travels by vibrating the particles of a medium such as air, water or metal, so in a vacuum there is nothing to carry the vibration. Light is electromagnetic and does travel through a vacuum — confusing the two kinds of wave is a common error. Therefore the correct answer is D: requires a material medium to transmit its vibrations.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, NULL),
('q_wisc_waves_b003_003', 'topic_wassce_intsci_waves', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A light ray strikes a plane mirror at an angle of incidence of 35°. What is the angle between the incident ray and the reflected ray?', 'multiple_choice', NULL, '["A. 70°","B. 35°","C. 55°","D. 90°"]', 'A', 'By the law of reflection the angle of reflection equals the angle of incidence, so both are 35° measured from the normal. The angle between the two rays is 35° + 35° = 70°. (55° is the angle between a ray and the mirror surface — measuring from the surface instead of the normal is the common slip.) Therefore the correct answer is A: 70°.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL),
('q_wisc_waves_b003_004', 'topic_wassce_intsci_waves', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A wave on water has a frequency of 50 Hz and a wavelength of 4 m. Calculate the speed of the wave.', 'calculation', NULL, NULL, '200 m/s', 'Wave speed = frequency × wavelength: v = fλ = 50 Hz × 4 m = 200 m/s. Answer: the wave travels at 200 m/s.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_waves_b003_005', 'topic_wassce_intsci_waves', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Light and sound are both forms of wave motion.', 'structured', NULL, NULL, '(a) Any two of: light travels through a vacuum but sound cannot; light travels much faster than sound (about 3 × 10⁸ m/s versus about 340 m/s in air); light is a transverse electromagnetic wave while sound is a longitudinal mechanical wave. (b) Speed = distance ÷ time = 1,700 m ÷ 5 s = 340 m/s.', '(a) Any two of: light travels through a vacuum but sound cannot; light travels much faster than sound (about 3 × 10⁸ m/s versus about 340 m/s in air); light is a transverse electromagnetic wave while sound is a longitudinal mechanical wave. (b) Speed = distance ÷ time = 1,700 m ÷ 5 s = 340 m/s.', 'medium', '4', '4', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL),
('q_wisc_acids_b003_001', 'topic_wassce_intsci_acids', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A student tests lemon juice and a dilute sodium hydroxide solution in the laboratory.', 'structured', NULL, NULL, '(a) The blue litmus paper turns red, showing that lemon juice is acidic. (b) Sodium chloride (common salt) and water: HCl + NaOH → NaCl + H₂O. (c) Any one of: treating acid indigestion with an antacid; adding lime to acidic soil; using toothpaste to neutralise acid produced on teeth.', '(a) The blue litmus paper turns red, showing that lemon juice is acidic. (b) Sodium chloride (common salt) and water: HCl + NaOH → NaCl + H₂O. (c) Any one of: treating acid indigestion with an antacid; adding lime to acidic soil; using toothpaste to neutralise acid produced on teeth.', 'medium', '4', '4', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL);
INSERT INTO _migration_590_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_wisc_waves_b003_005_a', 'q_wisc_waves_b003_005', 'a', 'State two differences between light waves and sound waves.', '2', 'Any two of: light travels through a vacuum but sound cannot; light travels much faster than sound (about 3 × 10⁸ m/s versus about 340 m/s in air); light is a transverse electromagnetic wave while sound is a longitudinal mechanical wave.', '1'),
('sqp_q_wisc_waves_b003_005_b', 'q_wisc_waves_b003_005', 'b', 'A sound wave travels 1,700 m through air in 5 s. Calculate the speed of sound in air.', '2', 'Speed = distance ÷ time = 1,700 m ÷ 5 s = 340 m/s.', '2'),
('sqp_q_wisc_acids_b003_001_a', 'q_wisc_acids_b003_001', 'a', 'State the colour change observed when blue litmus paper is dipped into the lemon juice.', '1', 'The blue litmus paper turns red, showing that lemon juice is acidic.', '1'),
('sqp_q_wisc_acids_b003_001_b', 'q_wisc_acids_b003_001', 'b', 'Name the salt formed when hydrochloric acid reacts completely with sodium hydroxide, and name the other product of the reaction.', '2', 'Sodium chloride (common salt) and water: HCl + NaOH → NaCl + H₂O.', '2'),
('sqp_q_wisc_acids_b003_001_c', 'q_wisc_acids_b003_001', 'c', 'State one everyday application of neutralisation.', '1', 'Any one of: treating acid indigestion with an antacid; adding lime to acidic soil; using toothpaste to neutralise acid produced on teeth.', '3');
INSERT INTO _migration_590_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_590_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_590_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_590_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_590_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_590_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_590_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_590_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_590_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_590_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_590_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_590_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 5 THEN 1 ELSE 0 END;
